mapper.select:
SELECT 
FROM TB_CALENDAR_DATE
WHERE LUNAR_YEAR = #{lunarYear}
  AND LUNAR_MONTH = #{lunarMonth}
  AND LUNAR_DAY = #{lunarDay}

  AND IS_LEAP_MONTH = #{isLeapMonth}

ORDER BY CAL_DATE

SELECT COUNT(*) > 0
FROM TB_CALENDAR_DATE
WHERE CAL_DATE = #{calDate}

SELECT COUNT(*)
FROM TB_CALENDAR_DATE
WHERE SOLAR_YEAR = #{year}

mapper.update:
UPDATE TB_CALENDAR_DATE
SET IS_HOLIDAY = #{isHoliday},
    HOLIDAY_NAME = #{holidayName},
    HOLIDAY_TYPE = #{holidayType},
    IS_WORKDAY = #{isWorkday}
WHERE CAL_DATE = #{calDate}
